// Standalone modern Inbox Management UI (Fixed Details, Search, No Overflow)
const INBOX_HTML_B64 = "";

export function getInboxHtml(): string {
    const binary = atob(INBOX_HTML_B64);
    const bytes = Uint8Array.from(binary, c => c.charCodeAt(0));
    return new TextDecoder("utf-8").decode(bytes);
}
